import { readFile, writeFile } from "node:fs/promises";
import { Interface } from "ethers";

async function abi(path) {
  const artifact = JSON.parse(
    await readFile(
      new URL(`../artifacts/contracts/${path}`, import.meta.url),
      "utf8",
    ),
  );
  return new Interface(artifact.abi).format();
}
const token = await abi("MockERC20.sol/MockERC20.json");
const pool = await abi("FairJackPool.sol/FairJackPool.json");
const oracle = await abi("test/MockVRFWrapper.sol/MockVRFWrapper.json");
const output =
  "// Generated by npm run abi:sync from the compiled Solidity artifacts.\n" +
  `export const mockTokenAbi = ${JSON.stringify(
    token,
    null,
    2,
  )} as const;\n\n` +
  `export const fairJackPoolAbi = ${JSON.stringify(
    pool,
    null,
    2,
  )} as const;\n\n` +
  `export const mockVrfWrapperAbi = ${JSON.stringify(
    oracle,
    null,
    2,
  )} as const;\n`;
await writeFile(
  new URL("../frontend/src/contracts/abis.ts", import.meta.url),
  output,
);
